catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    if (newValue == 'myself') {
        var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMFluClinicAjax');

        ga.addParam('sysparm_name', 'alreadyHaveAppointment');
        ga.addParam('sysparm_reason', g_form.getValue('reason'));
        ga.addParam('sysparm_user', g_user.userID);
        ga.getXML(function(response) {
            var answer = response.responseXML.documentElement.getAttribute('answer');

            if (answer) {
                //g_form.clearValue('already_have_an_active_appointment');
                //g_form.setValue('already_have_an_active_appointment', answer);
                getMessage('x_hccc_hoc_ohs.already_have_an_appointment', function(m) {
                    getMessage('x_hccc_hoc_ohs.reschedule_vaccination', function(x) {
                        spModal.alert(m + '<br /><br /><a href="services?id=ticket&is_new_order=true&table=x_hccc_hoc_ohs_vaccination_appointment&sys_id=' + answer + '" target="_blank">' + x + '</a>').then(function(answer) {
                            g_form.clearValue('who_are_you_booking_for');
                            g_form.clearValue('reason');
                        });
                    })

                })

            }
        });
    }

}
